-- Roadmap Phase 7 · authored recipes.
-- Generated by tool/recipe_pipeline/pipeline.dart from a
-- reviewed proposal file. Do not hand-edit: change the
-- proposal and re-run, so the validator sees the change.
--
-- Idempotent. Ids are derived from the proposal slug via
-- uuid_generate_v5 against a fixed namespace, so re-running
-- after an edit updates the same rows instead of inserting
-- a second copy of the catalogue.

begin;

create extension if not exists "uuid-ossp";

-- Salmon Donburi
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'salmon-donburi'),
  'Somonlu Donburi',
  'Salmon Donburi',
  'dinner',
  585, 42, 64, 18,
  25,
  'MALZEMELER:
- 170 g somon fileto
- 85 g pirinç (kuru ölçü)
- 2 yemek kaşığı soya sosu
- 1 yemek kaşığı mirin (tatlı pirinç sirkesi; bal ve su da olur)
- 1 çay kaşığı susam
- 1 yemek kaşığı yeşil soğan

HAZIRLANIŞI:
1. Pirinci pişirip sıcak tutun.
2. Soya sosu ve mirini hafif kıvam alana kadar 2 dakika kaynatın.
3. Somonu derili tarafı altta 4 dakika, sonra etli tarafı 2 dakika pişirin.
4. Somonu pilavın üzerine parçalayın, sosu gezdirin, susam ve yeşil soğanla bitirin.',
  'INGREDIENTS:
- 170 g salmon fillet
- 85 g sushi rice (dry weight)
- 2 yemek kaşığı soy sauce
- 1 yemek kaşığı mirin (sweet rice wine; honey and water works)
- 1 çay kaşığı sesame seeds
- 1 yemek kaşığı spring onion

METHOD:
1. Cook the rice and keep it warm.
2. Simmer the soy sauce and mirin for 2 minutes until slightly syrupy.
3. Sear the salmon skin-side down for 4 minutes, then 2 on the flesh.
4. Flake the salmon over the rice, pour the glaze on, and finish with sesame and spring onion.',
  ARRAY['high_protein', 'bulking']::text[],
  'japanese',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/salmon-donburi.webp'
)
on conflict (id) do update set
  title = excluded.title,
  title_en = excluded.title_en,
  meal_type = excluded.meal_type,
  calories = excluded.calories,
  protein = excluded.protein,
  carbs = excluded.carbs,
  fat = excluded.fat,
  prep_time_minutes = excluded.prep_time_minutes,
  instructions = excluded.instructions,
  instructions_en = excluded.instructions_en,
  tag_tokens = excluded.tag_tokens,
  cuisine = excluded.cuisine,
  diet_flags = excluded.diet_flags,
  locale_scope = excluded.locale_scope,
  image_url = excluded.image_url;

