-- Chicken Teriyaki with Rice
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-teriyaki-rice'),
  'Teriyaki Tavuk ve Pilav',
  'Chicken Teriyaki with Rice',
  'dinner',
  580, 48, 66, 14,
  25,
  'MALZEMELER:
- 180 g tavuk but
- 85 g yasemin pirinci (kuru ölçü)
- 2 yemek kaşığı soya sosu
- 1 yemek kaşığı bal
- 1 çay kaşığı zencefil rende
- 100 g brokoli

HAZIRLANIŞI:
1. Pirinci pişirin, son 5 dakikada brokoliyi üzerinde buharda haşlayın.
2. Tavuğu derili tarafı altta yağını salana kadar 6 dakika pişirin.
3. Çevirin, soya sosu, bal ve zencefili ekleyip sosu 4 dakika koyulaştırın.
4. Tavuğu dilimleyip brokoliyle birlikte pilavın üzerinde servis edin.',
  'INGREDIENTS:
- 180 g chicken thigh
- 85 g jasmine rice (dry weight)
- 2 yemek kaşığı soy sauce
- 1 yemek kaşığı honey
- 1 çay kaşığı grated ginger
- 100 g broccoli

METHOD:
1. Cook the rice and steam the broccoli over it for the last 5 minutes.
2. Sear the chicken skin-side down for 6 minutes until it renders.
3. Turn it, add the soy sauce, honey and ginger, and let the glaze reduce for 4 minutes.
4. Slice the chicken and serve it over the rice with the broccoli.',
  ARRAY['high_protein', 'bulking']::text[],
  'japanese',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/chicken-teriyaki-rice.webp'
)
