-- Miso Tofu Soup
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'miso-tofu-soup-bowl'),
  'Misolu Tofu Çorbası',
  'Miso Tofu Soup',
  'lunch',
  330, 28, 12, 19,
  15,
  'MALZEMELER:
- 200 g katı tofu
- 2 yemek kaşığı miso ezmesi (fermente soya ezmesi)
- 600 ml sebze suyu
- 50 g ıspanak
- 2 yemek kaşığı yeşil soğan
- 1 çay kaşığı susam yağı

HAZIRLANIŞI:
1. Sebze suyunu kaynama noktasının altında tutun — miso kaynayınca acılaşır.
2. Miso ezmesini bir kepçe suyla açıp tencereye geri karıştırın.
3. Küp doğranmış tofu ve ıspanağı ekleyip 3 dakika ısıtın.
4. Susam yağı ve yeşil soğanla bitirin.',
  'INGREDIENTS:
- 200 g firm tofu
- 2 yemek kaşığı miso paste (fermented soybean)
- 600 ml vegetable stock
- 50 g spinach
- 2 yemek kaşığı spring onion
- 1 çay kaşığı sesame oil

METHOD:
1. Bring the stock to a bare simmer — miso goes bitter if it boils.
2. Whisk the miso paste into a ladleful of stock, then stir it back in.
3. Add the cubed tofu and spinach and warm them for 3 minutes.
4. Finish with sesame oil and spring onion.',
  ARRAY['low_calorie', 'toning']::text[],
  'japanese',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/miso-tofu-soup-bowl.webp'
)
