-- Tamago Rice Breakfast Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'tamago-protein-breakfast'),
  'Tamagolu Kahvaltı Kasesi',
  'Tamago Rice Breakfast Bowl',
  'breakfast',
  420, 26, 52, 12,
  12,
  'MALZEMELER:
- 3 yumurta
- 80 g pirinç (kuru ölçü)
- 1 yemek kaşığı soya sosu
- 1 çay kaşığı susam yağı
- 1 yaprak nori (kurutulmuş deniz yosunu)

HAZIRLANIŞI:
1. Pirinci pişirin.
2. Yumurtaları soya sosuyla çırpın.
3. Yağlanmış kızgın tavada üç ince kat hâlinde pişirip her katı bir öncekinin üzerine sarın.
4. Ruloyu dilimleyip pilavın üzerine, koparılmış noriyle dizin.',
  'INGREDIENTS:
- 3 eggs
- 80 g rice (dry weight)
- 1 yemek kaşığı soy sauce
- 1 çay kaşığı sesame oil
- 1 yaprak nori (dried seaweed sheet)

METHOD:
1. Cook the rice.
2. Beat the eggs with the soy sauce.
3. Cook them in a hot oiled pan in three thin layers, rolling each one over the last.
4. Slice the roll and lay it on the rice with torn nori.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'japanese',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
