-- Tuna Edamame Rice Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'edamame-tuna-rice-bowl'),
  'Ton Balıklı Edamame Kasesi',
  'Tuna Edamame Rice Bowl',
  'lunch',
  490, 40, 56, 12,
  15,
  'MALZEMELER:
- 150 g ton balığı (suyu süzülmüş)
- 80 g pirinç (kuru ölçü)
- 80 g edamame
- 1 yemek kaşığı soya sosu
- 1 çay kaşığı susam yağı
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Pirinci pişirip hafif soğumaya bırakın.
2. Edamameyi kaynar suda 3 dakika ısıtın.
3. Ton balığını soya sosu ve susam yağıyla çatalla karıştırın.
4. Kaseyi kurup susamı serpin.',
  'INGREDIENTS:
- 150 g canned tuna (drained)
- 80 g rice (dry weight)
- 80 g edamame
- 1 yemek kaşığı soy sauce
- 1 çay kaşığı sesame oil
- 1 çay kaşığı sesame seeds

METHOD:
1. Cook the rice and let it cool slightly.
2. Warm the edamame in boiling water for 3 minutes.
3. Fork the tuna through the soy sauce and sesame oil.
4. Build the bowl and scatter the sesame seeds.',
