-- Huevos Rancheros
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'huevos-rancheros-protein'),
  'Huevos Rancheros',
  'Huevos Rancheros',
  'breakfast',
  500, 32, 44, 22,
  20,
  'MALZEMELER:
- 3 yumurta
- 2 mısır tortilla
- 150 g siyah fasulye
- 150 g doğranmış domates
- 1 kuru soğan
- 1 yemek kaşığı zeytinyağı
- kimyon, acı biber, tuz

HAZIRLANIŞI:
1. Soğanı yağda yumuşatın, sonra domatesi, kimyonu ve acı biberi ekleyin.
2. Sosu 8 dakika pişirip fasulyeyi içine karıştırın.
3. Tortillaları kuru tavada ısıtın.
4. Yumurtaları pişirip tortilla ve sosun üzerinde servis edin.',
  'INGREDIENTS:
- 3 eggs
- 2 corn tortillas
- 150 g black beans
- 150 g chopped tomatoes
- 1 onion
- 1 yemek kaşığı olive oil
- cumin, chilli, salt

METHOD:
1. Soften the onion in the oil, then add the tomatoes, cumin and chilli.
2. Simmer the sauce for 8 minutes and stir the beans through.
3. Warm the tortillas in a dry pan.
4. Fry the eggs and serve them over the tortillas and sauce.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'mexican',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
