-- Chicken Tinga Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-tinga-bowl'),
  'Tavuklu Tinga Kasesi',
  'Chicken Tinga Bowl',
  'dinner',
  550, 46, 56, 16,
  35,
  'MALZEMELER:
- 200 g tavuk göğsü
- 80 g pirinç (kuru ölçü)
- 200 g doğranmış domates
- 1 kuru soğan
- 2 diş sarımsak
- 1 yemek kaşığı zeytinyağı
- chipotle, kekik, tuz

HAZIRLANIŞI:
1. Tavuğu 15 dakika haşlayıp iki çatalla lif lif ayırın.
2. Domates, soğan, sarımsak ve chipotleyi blenderdan geçirerek sos yapın.
3. Sosu yağda 6 dakika kavurarak koyulaştırın.
4. Didilmiş tavuğu sosa karıştırıp pilavın üzerinde servis edin.',
  'INGREDIENTS:
- 200 g chicken breast
- 80 g rice (dry weight)
- 200 g chopped tomatoes
- 1 onion
- 2 diş garlic
- 1 yemek kaşığı olive oil
- chipotle, oregano, salt

METHOD:
1. Poach the chicken for 15 minutes, then shred it with two forks.
2. Blend the tomatoes, onion, garlic and chipotle into a sauce.
3. Fry the sauce in the oil for 6 minutes to deepen it.
4. Fold the shredded chicken through and serve over the rice.',
  ARRAY['high_protein', 'bulking']::text[],
  'mexican',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/chicken-tinga-bowl.webp'
)
