-- Black Bean and Quinoa Tacos
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'black-bean-quinoa-tacos'),
  'Siyah Fasulyeli Kinoa Taco',
  'Black Bean and Quinoa Tacos',
  'lunch',
  480, 22, 62, 16,
  20,
  'MALZEMELER:
- 150 g siyah fasulye
- 60 g kinoa (kuru ölçü)
- 3 mısır tortilla
- 1 avokado
- 1 misket limonu
- 1 avuç kişniş
- kimyon, tuz

HAZIRLANIŞI:
1. Kinoayı 15 dakika haşlayın.
2. Fasulyeyi kimyonla ısıtın ve kıvam için üçte birini ezin.
3. Kinoayı fasulyeye karıştırın.
4. Isıtılmış tortillaları doldurup avokado, kişniş ve misket limonuyla servis edin.',
  'INGREDIENTS:
- 150 g black beans
- 60 g quinoa (dry weight)
- 3 corn tortillas
- 1 avocado
- 1 lime
- 1 avuç coriander
- cumin, salt

METHOD:
1. Simmer the quinoa for 15 minutes.
2. Warm the beans with the cumin and mash a third of them for body.
3. Fold the quinoa through the beans.
4. Fill the warmed tortillas and top with avocado, coriander and lime.',
  ARRAY['budget_friendly', 'toning']::text[],
  'mexican',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/black-bean-quinoa-tacos.webp'
