-- Mexican Street Corn Salad
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'mexican-street-corn-salad'),
  'Meksika Sokak Mısırı Salatası',
  'Mexican Street Corn Salad',
  'snack',
  325, 12, 38, 14,
  15,
  'MALZEMELER:
- 300 g mısır
- 60 g beyaz peynir
- 2 yemek kaşığı süzme yoğurt
- 1 misket limonu
- 1 avuç kişniş
- 1 çay kaşığı toz acı biber

HAZIRLANIŞI:
1. Mısırı kuru kızgın tavada kabarana kadar, yaklaşık 6 dakika kavurun.
2. Yoğurt, misket limonu suyu ve acı biberi karıştırarak sos yapın.
3. Sıcak mısırı sosla harmanlayın.
4. Üzerine beyaz peyniri ufalayıp kişnişi serpin.',
  'INGREDIENTS:
- 300 g sweetcorn
- 60 g feta cheese
- 2 yemek kaşığı Greek yogurt
- 1 lime
- 1 avuç coriander
- 1 çay kaşığı chilli powder

METHOD:
1. Char the corn in a dry hot pan until it blisters, about 6 minutes.
2. Mix the yogurt, lime juice and chilli into a dressing.
3. Toss the warm corn through the dressing.
4. Crumble the feta over and scatter the coriander.',
  ARRAY['low_calorie', 'budget_friendly']::text[],
  'mexican',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/mexican-street-corn-salad.webp'
