-- Beef Barbacoa Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'beef-barbacoa-bowl'),
  'Barbacoa Dana Kasesi',
  'Beef Barbacoa Bowl',
  'dinner',
  600, 48, 52, 22,
  45,
  'MALZEMELER:
- 200 g dana kuşbaşı
- 80 g pirinç (kuru ölçü)
- 100 g siyah fasulye
- 200 ml et suyu
- 2 diş sarımsak
- 1 misket limonu
- kimyon, kekik, acı biber

HAZIRLANIŞI:
1. Eti her tarafı kızarana kadar mühürleyin, sonra et suyu, sarımsak ve baharatları ekleyin.
2. Kapağını kapatıp lif lif ayrılana kadar 35 dakika pişirin.
3. Eti didikleyip kalan suyu üzerinde koyulaştırın.
4. Pilav ve fasulyeyle, misket limonu sıkarak servis edin.',
  'INGREDIENTS:
- 200 g beef brisket
- 80 g rice (dry weight)
- 100 g black beans
- 200 ml beef stock
- 2 diş garlic
- 1 lime
- cumin, oregano, chilli

METHOD:
1. Brown the beef on every side, then add the stock, garlic and spices.
2. Cover and simmer for 35 minutes until it pulls apart.
3. Shred the beef and reduce the remaining liquid over it.
4. Serve over rice and beans with a squeeze of lime.',
  ARRAY['high_protein', 'bulking']::text[],
  'mexican',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/beef-barbacoa-bowl.webp'
