) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'mexican-chocolate-protein-pudding'),
  'Meksika Çikolatalı Protein Puding',
  'Mexican Chocolate Protein Pudding',
  'dessert',
  300, 30, 22, 10,
  10,
  'MALZEMELER:
- 35 g çikolatalı whey protein tozu
- 200 ml süt
- 2 yemek kaşığı chia tohumu
- 1 çay kaşığı tarçın
- 1 çimdik acı toz biber

HAZIRLANIŞI:
1. Her şeyi bir kavanozda çırpın.
2. Chia dibe çökmesin diye 5 dakika sonra tekrar çırpın.
3. 3 saat soğutun — bunu Meksika yapan acı biberdir ve bir tutam yeterlidir.',
  'INGREDIENTS:
- 35 g chocolate whey protein powder
- 200 ml milk
- 2 yemek kaşığı chia seeds
- 1 çay kaşığı cinnamon
- 1 çimdik cayenne pepper

METHOD:
1. Whisk everything together in a jar.
2. Whisk again after 5 minutes so the chia does not settle.
3. Chill for 3 hours — the cayenne is what makes it Mexican, and a pinch is enough.',
  ARRAY['high_protein', 'toning']::text[],
  'mexican',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
  ARRAY[]::text[],
  'photos/meals/mexican-chocolate-protein-pudding.webp'
)
