-- Paneer Tikka Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'paneer-tikka-bowl'),
  'Paneer Tikka Kasesi',
  'Paneer Tikka Bowl',
  'dinner',
  560, 34, 48, 26,
  30,
  'MALZEMELER:
- 200 g paneer (Hint taze peyniri)
- 70 g basmati pirinci (kuru ölçü)
- 120 g süzme yoğurt
- 1 yemek kaşığı zeytinyağı
- 2 çay kaşığı garam masala baharatı
- 1 çay kaşığı zencefil rende
- 1 renkli biber

HAZIRLANIŞI:
1. Küp doğranmış paneeri yoğurt, garam masala ve zencefille 15 dakika marine edin.
2. Pirinci pişirin.
3. Paneer ve biberi çok kızgın tavada kenarları yanana kadar, yaklaşık 8 dakika pişirin.
4. Kalan marinatı ısıtıp pilavın üzerinde servis edin.',
  'INGREDIENTS:
- 200 g paneer (Indian fresh cheese)
- 70 g basmati rice (dry weight)
- 120 g Greek yogurt
- 1 yemek kaşığı olive oil
- 2 çay kaşığı garam masala
- 1 çay kaşığı grated ginger
- 1 bell pepper

METHOD:
1. Marinate the cubed paneer in the yogurt, garam masala and ginger for 15 minutes.
2. Cook the rice.
3. Sear the paneer and pepper in a very hot pan until charred at the edges, about 8 minutes.
4. Serve over the rice with the remaining marinade warmed through.',
  ARRAY['high_protein', 'toning']::text[],
  'indian',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
  ARRAY[]::text[],
  'photos/meals/paneer-tikka-bowl.webp'
)
