-- Red Lentil Dal
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'red-lentil-dal'),
  'Kırmızı Mercimek Dal',
  'Red Lentil Dal',
  'lunch',
  450, 24, 62, 12,
  30,
  'MALZEMELER:
- 150 g kırmızı mercimek
- 600 ml sebze suyu
- 1 kuru soğan
- 2 diş sarımsak
- 1 çay kaşığı zerdeçal
- 1 çay kaşığı kimyon
- 1 yemek kaşığı hindistancevizi yağı

HAZIRLANIŞI:
1. Mercimeği suyu berraklaşana kadar yıkayın.
2. Soğan, sarımsak ve baharatları hindistancevizi yağında 4 dakika kavurun.
3. Mercimeği ve sebze suyunu ekleyip karıştırarak 22 dakika pişirin.
4. Kıvam alması için bir kısmını tencerenin kenarında ezin.',
  'INGREDIENTS:
- 150 g red lentils
- 600 ml vegetable stock
- 1 onion
- 2 diş garlic
- 1 çay kaşığı turmeric
- 1 çay kaşığı cumin
- 1 yemek kaşığı coconut oil

METHOD:
1. Rinse the lentils until the water runs clear.
2. Fry the onion, garlic and spices in the coconut oil for 4 minutes.
3. Add the lentils and stock and simmer for 22 minutes, stirring.
4. Mash a little against the side of the pan to thicken it.',
  ARRAY['budget_friendly', 'toning']::text[],
  'indian',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/red-lentil-dal.webp'
)
