-- Lighter Chicken Tikka Masala
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chicken-tikka-masala-light'),
  'Hafif Tavuklu Tikka Masala',
  'Lighter Chicken Tikka Masala',
  'dinner',
  580, 48, 52, 20,
  35,
  'MALZEMELER:
- 200 g tavuk göğsü
- 70 g basmati pirinci (kuru ölçü)
- 150 g süzme yoğurt
- 200 g doğranmış domates
- 2 çay kaşığı garam masala baharatı
- 1 çay kaşığı zencefil rende
- 1 yemek kaşığı zeytinyağı

HAZIRLANIŞI:
1. Küp doğranmış tavuğu yoğurdun yarısı ve baharatlarla 20 dakika marine edin.
2. Yağda kenarları yanana kadar yüksek ateşte mühürleyin.
3. Domatesi ekleyip 12 dakika pişirin.
4. Kalan yoğurdu ateşten uzakta karıştırın — kaynatmak sosu kestirir.
5. Basmati pilavının üzerinde servis edin.',
  'INGREDIENTS:
- 200 g chicken breast
- 70 g basmati rice (dry weight)
- 150 g Greek yogurt
- 200 g chopped tomatoes
- 2 çay kaşığı garam masala
- 1 çay kaşığı grated ginger
- 1 yemek kaşığı olive oil

METHOD:
1. Marinate the cubed chicken in half the yogurt with the spices for 20 minutes.
2. Sear it hard in the oil until charred at the edges.
3. Add the tomatoes and simmer for 12 minutes.
4. Stir the remaining yogurt in off the heat — boiling it splits the sauce.
5. Serve over the basmati.',
  ARRAY['high_protein', 'bulking']::text[],
  'indian',
  ARRAY['pork_free', 'gluten_free']::text[],
  ARRAY[]::text[],
  'photos/meals/chicken-tikka-masala-light.webp'
)
