-- Chana Masala
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'chana-masala'),
  'Nohutlu Chana Masala',
  'Chana Masala',
  'lunch',
  460, 20, 64, 14,
  25,
  'MALZEMELER:
- 300 g haşlanmış nohut
- 200 g doğranmış domates
- 1 kuru soğan
- 2 diş sarımsak
- 2 çay kaşığı garam masala baharatı
- 1 yemek kaşığı zeytinyağı
- 1 avuç kişniş

HAZIRLANIŞI:
1. Soğan ve sarımsağı koyu altın rengi olana kadar kavurun — lezzet buradan gelir, acele etmeyin.
2. Garam masalayı ekleyip 1 dakika pişirin.
3. Domates ve nohudu ekleyip 15 dakika pişirin.
4. Kişnişle bitirin.',
  'INGREDIENTS:
- 300 g chickpeas
- 200 g chopped tomatoes
- 1 onion
- 2 diş garlic
- 2 çay kaşığı garam masala
- 1 yemek kaşığı olive oil
- 1 avuç coriander

METHOD:
1. Fry the onion and garlic until deeply golden — this is where the flavour comes from, so do not rush it.
2. Add the garam masala and cook for 1 minute.
3. Add the tomatoes and chickpeas and simmer for 15 minutes.
4. Finish with coriander.',
  ARRAY['budget_friendly', 'toning']::text[],
  'indian',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/chana-masala.webp'
)
