-- Masala Egg Bhurji
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'masala-egg-bhurji'),
  'Baharatlı Yumurta Bhurji',
  'Masala Egg Bhurji',
  'breakfast',
  340, 26, 14, 20,
  15,
  'MALZEMELER:
- 4 yumurta
- 1 kuru soğan
- 1 domates
- 1 çay kaşığı zerdeçal
- 1 çay kaşığı kimyon
- 1 yemek kaşığı zeytinyağı
- 1 avuç kişniş

HAZIRLANIŞI:
1. Doğranmış soğanı yağda yumuşayana kadar kavurun.
2. Kimyon ve zerdeçalı ekleyip 30 saniye pişirin.
3. Doğranmış domatesi ekleyip 3 dakika suyunu çektirin.
4. Çırpılmış yumurtaları dökün ve masalanın içinde karıştırın.
5. Kişnişle bitirin.',
  'INGREDIENTS:
- 4 eggs
- 1 onion
- 1 tomato
- 1 çay kaşığı turmeric
- 1 çay kaşığı cumin
- 1 yemek kaşığı olive oil
- 1 avuç coriander

METHOD:
1. Fry the diced onion in the oil until it softens.
2. Add the cumin and turmeric and cook for 30 seconds.
3. Add the chopped tomato and cook it down for 3 minutes.
4. Pour in the beaten eggs and scramble them into the masala.
5. Finish with coriander.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'indian',
