-- Chicken Souvlaki Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'greek-chicken-souvlaki-bowl'),
  'Tavuklu Souvlaki Kasesi',
  'Chicken Souvlaki Bowl',
  'dinner',
  520, 48, 32, 22,
  25,
  'MALZEMELER:
- 200 g tavuk göğsü
- 150 g süzme yoğurt
- 1 salatalık
- 2 diş sarımsak
- 1 yemek kaşığı zeytinyağı
- 1 limon
- kekik, tuz, karabiber

HAZIRLANIŞI:
1. Küp doğranmış tavuğu zeytinyağı, limon suyu ve kekikle 20 dakika marine edin.
2. Salatalığı rendeleyip suyunu sıkın, yoğurt ve sarımsakla karıştırarak cacık yapın.
3. Tavuğu çevirerek 10 dakika, kenarları yanana kadar ızgarada pişirin.
4. Tavuğu cacığın üzerinde servis edin.',
  'INGREDIENTS:
- 200 g chicken breast
- 150 g Greek yogurt
- 1 cucumber
- 2 diş garlic
- 1 yemek kaşığı olive oil
- 1 lemon
- oregano, salt, pepper

METHOD:
1. Marinate the cubed chicken in the oil, lemon juice and oregano for 20 minutes.
2. Grate the cucumber, squeeze the water out, and mix it with the yogurt and garlic for the tzatziki.
3. Grill the chicken for 10 minutes, turning, until charred.
4. Serve the chicken over the tzatziki.',
  ARRAY['high_protein', 'toning']::text[],
  'greek',
  ARRAY['pork_free', 'gluten_free']::text[],
  ARRAY[]::text[],
  'photos/meals/greek-chicken-souvlaki-bowl.webp'
)
