-- Greek Salad with Feta
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'greek-salad-with-feta'),
  'Beyaz Peynirli Yunan Salatası',
  'Greek Salad with Feta',
  'lunch',
  390, 16, 18, 28,
  12,
  'MALZEMELER:
- 200 g domates
- 150 g salatalık
- 100 g beyaz peynir
- 60 g zeytin
- 1 kırmızı soğan
- 2 yemek kaşığı zeytinyağı
- kekik, tuz

HAZIRLANIŞI:
1. Domatesleri küp değil, dilim dilim kesin — Yunan salatası iri doğranır.
2. Salatalık ve soğanı dilimleyip zeytinlerle birleştirin.
3. Beyaz peyniri ufalamadan bütün hâlde üzerine koyun.
4. Zeytinyağını gezdirip kekik ve tuzla bitirin.',
  'INGREDIENTS:
- 200 g tomatoes
- 150 g cucumber
- 100 g feta cheese
- 60 g olives
- 1 red onion
- 2 yemek kaşığı olive oil
- oregano, salt

METHOD:
1. Cut the tomatoes into wedges rather than dice — a Greek salad is chunky.
2. Slice the cucumber and onion and combine them with the olives.
3. Lay the feta on top whole, not crumbled.
4. Pour the olive oil over and finish with oregano and salt.',
  ARRAY['low_calorie', 'toning']::text[],
  'greek',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
  ARRAY[]::text[],
  'photos/meals/greek-salad-with-feta.webp'
)
