-- Baked Peaches with Pistachios
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'greek-baked-peaches'),
  'Fırında Antep Fıstıklı Şeftali',
  'Baked Peaches with Pistachios',
  'dessert',
  285, 6, 34, 14,
  25,
  'MALZEMELER:
- 3 şeftali
- 30 g antep fıstığı
- 1 yemek kaşığı bal
- 1 çay kaşığı tarçın
- 1 limon

HAZIRLANIŞI:
1. Şeftalileri ikiye bölüp kesik yüzleri yukarı bakacak şekilde kaba dizin.
2. Bal ve limon suyunu gezdirip tarçın serpin.
3. Hafifçe çökene kadar 190 derecede 20 dakika pişirin.
4. Sıcakken üzerine doğranmış antep fıstığını serpin.',
  'INGREDIENTS:
- 3 peaches
- 30 g pistachios
- 1 yemek kaşığı honey
- 1 çay kaşığı cinnamon
- 1 lemon

METHOD:
1. Halve the peaches and set them cut-side up in a dish.
2. Drizzle the honey and lemon juice over and dust with cinnamon.
3. Bake at 190 degrees for 20 minutes until they collapse slightly.
4. Scatter the chopped pistachios over while they are still hot.',
  ARRAY['low_calorie', 'budget_friendly']::text[],
  'greek',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
