-- Baked Feta with Tomatoes
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'baked-feta-tomato-protein'),
  'Fırında Beyaz Peynir ve Domates',
  'Baked Feta with Tomatoes',
  'dinner',
  445, 22, 22, 30,
  30,
  'MALZEMELER:
- 150 g beyaz peynir
- 300 g cherry domates
- 2 diş sarımsak
- 2 yemek kaşığı zeytinyağı
- 1 avuç fesleğen
- kekik, karabiber

HAZIRLANIŞI:
1. Beyaz peyniri kabın ortasına koyup etrafına domates ve sarımsağı dizin.
2. Zeytinyağını üzerine gezdirip tatlandırın.
3. Domatesler patlayana kadar 200 derecede 25 dakika pişirin.
4. Hepsini karıştırıp fesleğenle bitirin.',
  'INGREDIENTS:
- 150 g feta cheese
- 300 g cherry tomatoes
- 2 diş garlic
- 2 yemek kaşığı olive oil
- 1 avuç basil
- oregano, pepper

METHOD:
1. Put the feta in the middle of a dish and surround it with the tomatoes and garlic.
2. Pour the olive oil over everything and season.
3. Bake at 200 degrees for 25 minutes until the tomatoes burst.
4. Stir it all together and finish with basil.',
  ARRAY['toning', 'low_calorie']::text[],
  'greek',
  ARRAY['vegetarian', 'pork_free', 'gluten_free']::text[],
