-- Chicken Shawarma Plate
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'shawarma-chicken-plate'),
  'Tavuk Shawarma Tabağı',
  'Chicken Shawarma Plate',
  'dinner',
  575, 46, 48, 22,
  30,
  'MALZEMELER:
- 200 g tavuk but
- 100 g pilavlık bulgur (kuru ölçü)
- 2 yemek kaşığı tahin
- 1 limon
- 2 çay kaşığı baharat karışımı
- 1 yemek kaşığı zeytinyağı
- 1 domates

HAZIRLANIŞI:
1. Dilimlenmiş tavuğu baharat karışımı ve yağla harmanlayıp 15 dakika bekletin.
2. Bulguru iki katı suda 12 dakika pişirin.
3. Tavuğu kenarları çıtırlaşana kadar yüksek ateşte kızartın.
4. Tahini limon suyu ve suyla açıp üzerine gezdirin.',
  'INGREDIENTS:
- 200 g chicken thigh
- 100 g bulgur (dry weight)
- 2 yemek kaşığı tahini
- 1 lemon
- 2 çay kaşığı baharat spice mix
- 1 yemek kaşığı olive oil
- 1 tomato

METHOD:
1. Toss the sliced chicken in the spice mix and oil and leave it for 15 minutes.
2. Cook the bulgur in twice its volume of water for 12 minutes.
3. Sear the chicken hard until the edges crisp.
4. Loosen the tahini with lemon juice and water and pour it over.',
  ARRAY['high_protein', 'bulking']::text[],
  'levantine',
  ARRAY['pork_free', 'dairy_free']::text[],
