-- Baked Falafel Bowl
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'falafel-protein-bowl'),
  'Fırında Falafel Kasesi',
  'Baked Falafel Bowl',
  'lunch',
  510, 24, 58, 20,
  35,
  'MALZEMELER:
- 300 g haşlanmış nohut
- 1 kuru soğan
- 3 diş sarımsak
- 1 avuç maydanoz
- 2 yemek kaşığı tahin
- 2 çay kaşığı kimyon
- 1 yemek kaşığı zeytinyağı

HAZIRLANIŞI:
1. Nohut, soğan, sarımsak, maydanoz ve kimyonu iri taneli bir hamur olana kadar çekin — pürüzsüz hamur falafeli ağırlaştırır.
2. 10 köfte şekli verip üzerlerine yağ sürün.
3. 200 derecede bir kez çevirerek 25 dakika pişirin.
4. Tahini su ve limonla açıp yanında servis edin.',
  'INGREDIENTS:
- 300 g chickpeas
- 1 onion
- 3 diş garlic
- 1 avuç parsley
- 2 yemek kaşığı tahini
- 2 çay kaşığı cumin
- 1 yemek kaşığı olive oil

METHOD:
1. Blitz the chickpeas, onion, garlic, parsley and cumin to a coarse paste — a smooth one makes falafel dense.
2. Shape into 10 patties and brush them with the oil.
3. Bake at 200 degrees for 25 minutes, turning once.
4. Loosen the tahini with water and lemon and serve alongside.',
  ARRAY['budget_friendly', 'toning']::text[],
  'levantine',
  ARRAY['vegan', 'vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
