-- Shakshuka
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'shakshuka-protein'),
  'Şakşuka',
  'Shakshuka',
  'breakfast',
  405, 26, 26, 22,
  25,
  'MALZEMELER:
- 4 yumurta
- 400 g doğranmış domates
- 1 renkli biber
- 1 kuru soğan
- 2 diş sarımsak
- 1 yemek kaşığı zeytinyağı
- kimyon, toz biber, tuz

HAZIRLANIŞI:
1. Soğan ve biberi yağda 8 dakika yumuşatın.
2. Sarımsak ve baharatları, sonra domatesi ekleyip 10 dakika pişirin.
3. Dört çukur açıp her birine bir yumurta kırın.
4. Kapağını kapatıp beyazları donana, sarılar akışkan kalana kadar 6 dakika pişirin.',
  'INGREDIENTS:
- 4 eggs
- 400 g chopped tomatoes
- 1 bell pepper
- 1 onion
- 2 diş garlic
- 1 yemek kaşığı olive oil
- cumin, paprika, salt

METHOD:
1. Soften the onion and pepper in the oil for 8 minutes.
2. Add the garlic and spices, then the tomatoes, and simmer for 10 minutes.
3. Make four wells and crack an egg into each.
4. Cover and cook for 6 minutes until the whites set and the yolks stay soft.',
  ARRAY['high_protein', 'budget_friendly']::text[],
  'levantine',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
