-- Muhammara with Vegetables
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'muhammara-protein-dip'),
  'Sebzeli Muhammara',
  'Muhammara with Vegetables',
  'snack',
  395, 10, 30, 26,
  15,
  'MALZEMELER:
- 200 g ızgara kırmızı biber
- 60 g ceviz
- 30 g galeta unu
- 1 yemek kaşığı nar ekşisi
- 2 yemek kaşığı zeytinyağı
- 1 çay kaşığı kimyon
- 150 g salatalık çubukları

HAZIRLANIŞI:
1. Biberleri, cevizi, galeta ununu, kimyonu ve nar ekşisini iri taneli bir ezme olana kadar çekin.
2. Zeytinyağıyla kaşıkla alınabilecek kıvama getirin.
3. Galeta unu şişsin diye 10 dakika dinlendirin.
4. Salatalık çubuklarıyla servis edin.',
  'INGREDIENTS:
- 200 g roasted red peppers
- 60 g walnuts
- 30 g breadcrumbs
- 1 yemek kaşığı pomegranate molasses
- 2 yemek kaşığı olive oil
- 1 çay kaşığı cumin
- 150 g cucumber sticks

METHOD:
1. Blitz the peppers, walnuts, breadcrumbs, cumin and pomegranate molasses to a coarse paste.
2. Loosen it with the olive oil until it is spoonable.
3. Rest it for 10 minutes so the breadcrumbs swell.
4. Serve with the cucumber sticks.',
  ARRAY['budget_friendly', 'toning']::text[],
  'levantine',
  ARRAY['vegan', 'vegetarian', 'pork_free', 'dairy_free']::text[],
  ARRAY[]::text[],
