-- Tabbouleh with Chickpeas
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'tabbouleh-protein-salad'),
  'Nohutlu Tabule',
  'Tabbouleh with Chickpeas',
  'lunch',
  380, 16, 48, 14,
  20,
  'MALZEMELER:
- 60 g ince bulgur (kuru ölçü)
- 150 g haşlanmış nohut
- 2 demet maydanoz
- 2 domates
- 1 limon
- 2 yemek kaşığı zeytinyağı
- 1 avuç nane

HAZIRLANIŞI:
1. Bulguru ılık suda 15 dakika bekletip iyice süzün.
2. Maydanozu çok ince kıyın — tabule, içinde bulgur olan bir yeşillik salatasıdır, tersi değil.
3. Domatesleri küp doğrayıp hepsini birleştirin.
4. Limon suyu ve zeytinyağıyla harmanlayıp 10 dakika dinlendirin.',
  'INGREDIENTS:
- 60 g fine bulgur (dry weight)
- 150 g chickpeas
- 2 demet parsley
- 2 tomatoes
- 1 lemon
- 2 yemek kaşığı olive oil
- 1 avuç mint

METHOD:
1. Soak the bulgur in warm water for 15 minutes and drain it well.
2. Chop the parsley very fine — tabbouleh is a herb salad with bulgur in it, not the other way round.
3. Dice the tomatoes and combine everything.
4. Dress with lemon juice and olive oil and rest for 10 minutes.',
  ARRAY['low_calorie', 'budget_friendly']::text[],
  'levantine',
  ARRAY['vegan', 'vegetarian', 'pork_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/tabbouleh-protein-salad.webp'
)
