-- Korean Soft Tofu Stew
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'korean-tofu-stew'),
  'Kore Usulü Tofu Güveci',
  'Korean Soft Tofu Stew',
  'dinner',
  345, 26, 24, 16,
  25,
  'MALZEMELER:
- 300 g yumuşak tofu
- 500 ml sebze suyu
- 1 yemek kaşığı gochujang (Kore acı biber ezmesi)
- 1 kabak
- 1 yumurta
- 2 yemek kaşığı yeşil soğan
- 1 çay kaşığı susam yağı

HAZIRLANIŞI:
1. Gochujangı sebze suyunda eritip kaynama noktasına getirin.
2. Dilimlenmiş kabağı ekleyip 5 dakika pişirin.
3. Tofuyu iri parçalar hâlinde kaşıkla ekleyin — dağıtmak dokusunu bozar.
4. Yumurtayı kırın, 2 dakika kapağını kapatın, susam yağı ve yeşil soğanla bitirin.',
  'INGREDIENTS:
- 300 g silken tofu
- 500 ml vegetable stock
- 1 yemek kaşığı gochujang (Korean chilli paste)
- 1 courgette
- 1 egg
- 2 yemek kaşığı spring onion
- 1 çay kaşığı sesame oil

METHOD:
1. Dissolve the gochujang in the stock and bring it to a simmer.
2. Add the sliced courgette and cook for 5 minutes.
3. Spoon the tofu in whole chunks — breaking it up makes it grainy.
4. Crack the egg in, cover for 2 minutes, and finish with sesame oil and spring onion.',
  ARRAY['toning', 'low_calorie']::text[],
  'korean',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/korean-tofu-stew.webp'
)
