-- Beef Bibimbap
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'bibimbap-protein-bowl'),
  'Etli Bibimbap',
  'Beef Bibimbap',
  'dinner',
  620, 42, 68, 20,
  35,
  'MALZEMELER:
- 150 g yağsız dana kıyma
- 85 g pirinç (kuru ölçü)
- 100 g ıspanak
- 80 g havuç
- 1 yumurta
- 1 yemek kaşığı gochujang
- 1 yemek kaşığı susam yağı

HAZIRLANIŞI:
1. Pirinci pişirin.
2. Kıymayı susam yağının yarısıyla kavurun.
3. Ispanağı haşlayın, havucu jülyen doğrayın ve her birini ayrı ayrı tatlandırın — bibimbap malzemelerini sofraya kadar ayrı tutar.
4. Hepsini pilavın üzerine dizin, sahanda yumurta ve gochujang ekleyin.',
  'INGREDIENTS:
- 150 g lean ground beef
- 85 g rice (dry weight)
- 100 g spinach
- 80 g carrot
- 1 egg
- 1 yemek kaşığı gochujang
- 1 yemek kaşığı sesame oil

METHOD:
1. Cook the rice.
2. Brown the beef with half the sesame oil.
3. Blanch the spinach and julienne the carrot, dressing each separately — bibimbap keeps its components apart until the table.
4. Arrange everything over the rice, top with a fried egg and the gochujang.',
  ARRAY['high_protein', 'bulking']::text[],
  'korean',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/bibimbap-protein-bowl.webp'
)
