-- Korean Chicken Lettuce Wraps
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'korean-chicken-lettuce-wraps'),
  'Kore Usulü Tavuklu Marul Sarma',
  'Korean Chicken Lettuce Wraps',
  'lunch',
  360, 40, 18, 14,
  20,
  'MALZEMELER:
- 200 g tavuk göğsü
- 8 yaprak marul yaprağı
- 1 yemek kaşığı gochujang
- 1 yemek kaşığı soya sosu
- 1 çay kaşığı zencefil rende
- 1 çay kaşığı susam yağı
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Tavuğu küp doğrayıp gochujang, soya sosu ve zencefille harmanlayın.
2. Susam yağında yüksek ateşte 7 dakika kızartın.
3. Marul yapraklarına doldurup susam serpin.',
  'INGREDIENTS:
- 200 g chicken breast
- 8 yaprak lettuce leaves
- 1 yemek kaşığı gochujang
- 1 yemek kaşığı soy sauce
- 1 çay kaşığı grated ginger
- 1 çay kaşığı sesame oil
- 1 çay kaşığı sesame seeds

METHOD:
1. Dice the chicken and toss it with the gochujang, soy sauce and ginger.
2. Sear it in the sesame oil over high heat for 7 minutes.
3. Spoon into lettuce leaves and scatter the sesame seeds.',
