-- Kimchi Fried Rice with Egg
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'kimchi-fried-rice-protein'),
  'Yumurtalı Kimchi Pilavı',
  'Kimchi Fried Rice with Egg',
  'lunch',
  500, 22, 62, 18,
  15,
  'MALZEMELER:
- 200 g pişmiş pirinç
- 120 g kimchi (fermente lahana)
- 2 yumurta
- 1 yemek kaşığı susam yağı
- 1 yemek kaşığı soya sosu
- 2 yemek kaşığı yeşil soğan

HAZIRLANIŞI:
1. Doğranmış kimchiyi susam yağında 3 dakika kavurun.
2. Pilavı ekleyin — bir günlük pilav daha iyidir, taze pilav kızarmak yerine buharlanır — ve 4 dakika soteleyin.
3. Kenara itip boşlukta yumurtaları karıştırın, sonra hepsini birleştirin.
4. Soya sosu ve yeşil soğanla bitirin.',
  'INGREDIENTS:
- 200 g cooked rice
- 120 g kimchi (fermented cabbage)
- 2 eggs
- 1 yemek kaşığı sesame oil
- 1 yemek kaşığı soy sauce
- 2 yemek kaşığı spring onion

METHOD:
1. Fry the chopped kimchi in the sesame oil for 3 minutes.
2. Add the rice — day-old is better, fresh rice steams instead of frying — and stir-fry for 4 minutes.
3. Push it aside, scramble the eggs in the space, then fold everything together.
4. Finish with soy sauce and spring onion.',
  ARRAY['budget_friendly', 'bulking']::text[],
  'korean',
  ARRAY['vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
