-- Beef Bulgogi
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'korean-beef-bulgogi'),
  'Bulgogi Dana Eti',
  'Beef Bulgogi',
  'dinner',
  590, 44, 58, 20,
  25,
  'MALZEMELER:
- 180 g dana bonfile
- 85 g pirinç (kuru ölçü)
- 2 yemek kaşığı soya sosu
- 1 armut (eti yumuşatır; atlamayın)
- 2 diş sarımsak
- 1 yemek kaşığı susam yağı
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Armudu rendeleyip soya sosu, sarımsak ve susam yağıyla karıştırın.
2. Eti kâğıt inceliğinde dilimleyip 20 dakika marine edin.
3. Pirinci pişirin.
4. Eti çok kızgın tavada 2 dakika mühürleyin — daha uzunu haşlar.
5. Susamla birlikte pilavın üzerinde servis edin.',
  'INGREDIENTS:
- 180 g beef sirloin
- 85 g rice (dry weight)
- 2 yemek kaşığı soy sauce
- 1 pear (the tenderiser; do not skip it)
- 2 diş garlic
- 1 yemek kaşığı sesame oil
- 1 çay kaşığı sesame seeds

METHOD:
1. Grate the pear and mix it with the soy sauce, garlic and sesame oil.
2. Slice the beef paper-thin and marinate it for 20 minutes.
3. Cook the rice.
4. Sear the beef in a screaming-hot pan for 2 minutes — any longer and it stews.
5. Serve over the rice with sesame seeds.',
  ARRAY['high_protein', 'bulking']::text[],
  'korean',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/korean-beef-bulgogi.webp'
)
