-- Thai Basil Chicken
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'thai-basil-chicken'),
  'Tayland Usulü Fesleğenli Tavuk',
  'Thai Basil Chicken',
  'dinner',
  580, 44, 60, 18,
  20,
  'MALZEMELER:
- 200 g tavuk göğsü
- 85 g yasemin pirinci (kuru ölçü)
- 1 avuç fesleğen
- 2 yemek kaşığı soya sosu
- 2 diş sarımsak
- 1 yemek kaşığı susam yağı
- pul biber

HAZIRLANIŞI:
1. Pirinci pişirin.
2. Tavuğu dilimlemek yerine ufak doğrayın — bu yemeğin özü dokusudur.
3. Sarımsak ve pul biberi yağda 30 saniye kavurun.
4. Tavuğu ve soya sosunu ekleyip 6 dakika soteleyin.
5. Ateşi kapatıp fesleğeni pişmeden solacak şekilde karıştırın.',
  'INGREDIENTS:
- 200 g chicken breast
- 85 g jasmine rice (dry weight)
- 1 avuç basil
- 2 yemek kaşığı soy sauce
- 2 diş garlic
- 1 yemek kaşığı sesame oil
- chilli flakes

METHOD:
1. Cook the rice.
2. Chop the chicken small rather than slicing it — the texture is the point of this dish.
3. Fry the garlic and chilli in the oil for 30 seconds.
4. Add the chicken and soy sauce and stir-fry for 6 minutes.
5. Kill the heat and fold the basil through so it wilts rather than cooks.',
  ARRAY['high_protein', 'bulking']::text[],
  'thai',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/thai-basil-chicken.webp'
)
