-- Thai Green Curry with Tofu
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'thai-green-curry-tofu'),
  'Tayland Yeşil Köri ve Tofu',
  'Thai Green Curry with Tofu',
  'dinner',
  570, 24, 56, 28,
  25,
  'MALZEMELER:
- 250 g katı tofu
- 80 g yasemin pirinci (kuru ölçü)
- 200 ml hindistan cevizi sütü
- 2 yemek kaşığı yeşil köri ezmesi
- 100 g taze fasulye
- 1 misket limonu
- 1 avuç fesleğen

HAZIRLANIŞI:
1. Köri ezmesini bir miktar hindistan cevizi sütünde 2 dakika, baharatların kokusu çıkana kadar kavurun.
2. Kalan hindistan cevizi sütünü ekleyip kaynama noktasına getirin.
3. Küp doğranmış tofu ve taze fasulyeyi ekleyip 8 dakika pişirin.
4. Ateşten aldıktan sonra misket limonu suyu ve fesleğenle bitirin.',
  'INGREDIENTS:
- 250 g firm tofu
- 80 g jasmine rice (dry weight)
- 200 ml coconut milk
- 2 yemek kaşığı green curry paste
- 100 g green beans
- 1 lime
- 1 avuç basil

METHOD:
1. Fry the curry paste in a splash of the coconut milk for 2 minutes until it smells of the spices.
2. Add the rest of the coconut milk and bring it to a simmer.
3. Add the cubed tofu and green beans and cook for 8 minutes.
4. Finish with lime juice and basil off the heat.',
  ARRAY['toning', 'budget_friendly']::text[],
  'thai',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/thai-green-curry-tofu.webp'
)
