-- Thai Beef Salad
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'thai-beef-salad'),
  'Tayland Usulü Etli Salata',
  'Thai Beef Salad',
  'lunch',
  395, 42, 16, 18,
  20,
  'MALZEMELER:
- 180 g dana bonfile
- 120 g salatalık
- 80 g cherry domates
- 1 misket limonu
- 1 yemek kaşığı soya sosu
- 1 avuç nane
- pul biber

HAZIRLANIŞI:
1. Eti her yüzü 3 dakika mühürleyip 5 dakika dinlendirin.
2. Misket limonu suyu, soya sosu ve pul biberi çırparak sos yapın.
3. Eti liflerine dik ince dilimleyin.
4. Salatalık, domates ve naneyle birlikte sosta harmanlayın.',
  'INGREDIENTS:
- 180 g beef sirloin
- 120 g cucumber
- 80 g cherry tomatoes
- 1 lime
- 1 yemek kaşığı soy sauce
- 1 avuç mint
- chilli flakes

METHOD:
1. Sear the beef 3 minutes a side and rest it for 5.
2. Whisk the lime juice, soy sauce and chilli into a dressing.
3. Slice the beef thinly against the grain.
4. Toss it with the cucumber, tomatoes and mint in the dressing.',
  ARRAY['high_protein', 'low_calorie']::text[],
  'thai',
  ARRAY['pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
  'photos/meals/thai-beef-salad.webp'
)
