-- Mango Coconut Protein Rice
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'thai-mango-sticky-protein'),
  'Mangolu Hindistan Cevizli Protein Pirinç',
  'Mango Coconut Protein Rice',
  'dessert',
  495, 20, 72, 14,
  30,
  'MALZEMELER:
- 80 g pirinç (kuru ölçü)
- 150 ml hindistan cevizi sütü
- 150 g mango
- 20 g vanilyalı whey protein tozu
- 1 yemek kaşığı bal
- 1 çay kaşığı susam

HAZIRLANIŞI:
1. Pirinci pişirip sıcakken hindistan cevizi sütünün çoğunu ve balı içine karıştırın.
2. Ilıyana kadar bekletip protein tozunu ekleyin — sıcak sıvı tozu topaklandırır.
3. Mangoyu dilimleyip yanına dizin.
4. Kalan hindistan cevizi sütünü gezdirip susam serpin.',
  'INGREDIENTS:
- 80 g rice (dry weight)
- 150 ml coconut milk
- 150 g mango
- 20 g vanilla whey protein powder
- 1 yemek kaşığı honey
- 1 çay kaşığı sesame seeds

METHOD:
1. Cook the rice, then stir most of the coconut milk and the honey through it while it is hot.
2. Let it cool to warm, then stir the protein powder in — hot liquid makes it grainy.
3. Slice the mango and lay it alongside.
4. Pour the remaining coconut milk over and scatter the sesame seeds.',
  ARRAY['high_protein', 'bulking']::text[],
  'thai',
  ARRAY[]::text[],
  ARRAY[]::text[],
  'photos/meals/thai-mango-sticky-protein.webp'
)
