-- Tuscan White Bean Soup
insert into public.recipes (
  id, title, title_en, meal_type, calories, protein, carbs,
  fat, prep_time_minutes, instructions, instructions_en,
  tag_tokens, cuisine, diet_flags, locale_scope, image_url
) values (
  uuid_generate_v5('8f7e6d5c-4b3a-2910-8f7e-6d5c4b3a2910'::uuid, 'tuscan-white-bean-soup'),
  'Toskana Beyaz Fasulye Çorbası',
  'Tuscan White Bean Soup',
  'lunch',
  395, 20, 52, 12,
  30,
  'MALZEMELER:
- 300 g haşlanmış kuru fasulye
- 600 ml sebze suyu
- 1 havuç
- 1 kuru soğan
- 2 diş sarımsak
- 2 yemek kaşığı zeytinyağı
- 1 dal taze biberiye

HAZIRLANIŞI:
1. Doğranmış soğan, havuç ve sarımsağı yağda 8 dakika yumuşatın.
2. Fasulye, sebze suyu ve biberiyeyi ekleyip 18 dakika pişirin.
3. Çorbanın üçte birini blenderdan geçirip geri karıştırın — kremasız kremamsılık buradan gelir.
4. Bolca zeytinyağı gezdirerek bitirin.',
  'INGREDIENTS:
- 300 g white beans
- 600 ml vegetable stock
- 1 carrot
- 1 onion
- 2 diş garlic
- 2 yemek kaşığı olive oil
- 1 dal rosemary

METHOD:
1. Soften the diced onion, carrot and garlic in the oil for 8 minutes.
2. Add the beans, stock and rosemary and simmer for 18 minutes.
3. Blend a third of the soup and stir it back in — that is what makes it creamy without cream.
4. Finish with a hard drizzle of olive oil.',
  ARRAY['budget_friendly', 'toning']::text[],
  'italian',
  ARRAY['vegan', 'vegetarian', 'pork_free', 'gluten_free', 'dairy_free']::text[],
  ARRAY[]::text[],
